function Assert-M12TrustedTree([string] $Path) { $full=[IO.Path]::GetFullPath($Path); $root=[IO.Path]::GetPathRoot($full); $cursor=$root; foreach($part in ($full.Substring($root.Length)-split '[\\/]')) { if([string]::IsNullOrEmpty($part)){continue}; $cursor=Join-Path $cursor $part; if(-not(Test-Path -LiteralPath $cursor)){continue}; $item=Get-Item -LiteralPath $cursor -Force; if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0){Fail-M12 'PATH'}; if([IO.Path]::GetFileName($cursor)-match '[:\x00]'){Fail-M12 'PATH'} } }
function Get-M12ReportsEnvItem([string]$Name){$item=$null;try{$item=Get-Item -LiteralPath ('Env:'+$Name) -ErrorAction Stop}catch{};$item}
function Save-M12ReportsEnvironment([string[]]$Names){$state=[ordered]@{};foreach($name in $Names){$item=Get-M12ReportsEnvItem $name;$state[$name]=[pscustomobject]@{Present=($null-ne$item);Value=if($null-ne$item){[string]$item.Value}else{$null}}};$state}
function Remove-M12ReportsEnvironment([string]$Name){if($null-ne(Get-M12ReportsEnvItem $Name)){Remove-Item -LiteralPath ('Env:'+$Name) -Force -ErrorAction Stop};if($null-ne(Get-M12ReportsEnvItem $Name)){Fail-M12 'PROCESS'}}
function Restore-M12ReportsEnvironment([hashtable]$State){$error=$null;foreach($name in $State.Keys){try{$expected=$State[$name];if($expected.Present){[Environment]::SetEnvironmentVariable($name,[string]$expected.Value,'Process')}else{Remove-M12ReportsEnvironment $name};$actual=Get-M12ReportsEnvItem $name;if(([bool]($null-ne$actual))-ne[bool]$expected.Present-or$expected.Present-and[string]$actual.Value-cne[string]$expected.Value){Fail-M12 'PROCESS'}}catch{if($null-eq$error){$error=$_}}};if($null-ne$error){throw$error}}
function Invoke-M12GitStatus([string]$Root,[string]$Git){
    $names=@('GIT_DIR','GIT_WORK_TREE','GIT_INDEX_FILE','GIT_CONFIG','GIT_CONFIG_GLOBAL','GIT_CONFIG_SYSTEM','GIT_CONFIG_NOSYSTEM','GIT_CONFIG_COUNT','GIT_TERMINAL_PROMPT','GIT_PAGER','GIT_ASKPASS','SSH_ASKPASS','GCM_INTERACTIVE');$saved=Save-M12ReportsEnvironment $names
    $native=$null;$handle=$null;$cleanupFailure=$false
    try{
        foreach($name in $names){Remove-M12ReportsEnvironment $name}
        [Environment]::SetEnvironmentVariable('GIT_CONFIG_NOSYSTEM','1');[Environment]::SetEnvironmentVariable('GIT_CONFIG_GLOBAL','NUL');[Environment]::SetEnvironmentVariable('GIT_CONFIG_SYSTEM','NUL');[Environment]::SetEnvironmentVariable('GIT_CONFIG_COUNT','0');[Environment]::SetEnvironmentVariable('GIT_TERMINAL_PROMPT','0');[Environment]::SetEnvironmentVariable('GIT_PAGER','cat');[Environment]::SetEnvironmentVariable('GIT_ASKPASS','');[Environment]::SetEnvironmentVariable('GCM_INTERACTIVE','Never')
        $arguments=@('-c','core.fsmonitor=false','-c','core.pager=cat','-c','core.askPass=','-c','credential.helper=','-c','core.hooksPath=NUL','--no-optional-locks','-C',$Root,'status','--porcelain=v1','--untracked-files=all','--no-renames')
        $handle=Open-M12ExecutableHandle $Git;$native=[M12SuspendedProcess]::Start($Git,[string[]]$arguments,$Root);$run=Invoke-M12BoundedProcess $Git $arguments $Root $native
        if($run.TimedOut-or$run.TooLarge-or$run.ExitCode-ne 0-or-not[string]::IsNullOrEmpty($run.Output.Trim())-or-not[string]::IsNullOrEmpty($run.Error.Trim())){Fail-M12 'COMMIT'}
    }finally{
        try{if($null-ne$native){if($native.ActiveProcesses-gt 0){$native.Terminate()};if(-not$native.WaitForZero(2000)-or$native.ActiveProcesses-ne 0){$cleanupFailure=$true}}}catch{$cleanupFailure=$true}
        try{if($null-ne$native){$native.Dispose()}}catch{$cleanupFailure=$true}
        try{if($null-ne$handle){$handle.Stream.Dispose()}}catch{$cleanupFailure=$true}
        try{Restore-M12ReportsEnvironment $saved}catch{$cleanupFailure=$true}
        if($cleanupFailure){Fail-M12 'PROCESS'}
    }
}
function Assert-M12CleanTree([string]$Root){$git=Join-Path ([Environment]::GetFolderPath([Environment+SpecialFolder]::ProgramFiles)) 'Git/bin/git.exe';if(-not(Test-Path -LiteralPath $git -PathType Leaf)){Fail-M12 'COMMIT'};Assert-M12TrustedTree $git;Invoke-M12GitStatus $Root $git}
function Get-M12RequiredValue([string] $Name) { $v=[Environment]::GetEnvironmentVariable($Name); if([String]::IsNullOrWhiteSpace($v)-or $v.Length -gt 4096){Fail-M12 'INPUT'}; return $v }
function Normalize-M12NativePath([string] $Path) { if($Path.StartsWith('\\?\UNC\',[StringComparison]::OrdinalIgnoreCase)){return '\\'+$Path.Substring(8)};if($Path.StartsWith('\\?\',[StringComparison]::OrdinalIgnoreCase)){return $Path.Substring(4)};return $Path }
function Assert-M12OutputFileIdentity([string] $Path,[string] $ExpectedDirectory) { $full=[IO.Path]::GetFullPath($Path);$directory=[IO.Path]::GetFullPath($ExpectedDirectory).TrimEnd('\\','/');if(-not $full.StartsWith($directory+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)-or [IO.Path]::GetFileName($full)-notmatch '^[a-z0-9-]+\.(json|trx)$'){Fail-M12 'OUTPUT'};Assert-M12TrustedTree $full;$s=[IO.FileStream]::new($full,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$i=[M12OutputFile]::Read($s);if($i.Links -ne 1-or [IO.Path]::GetFullPath((Normalize-M12NativePath $i.FinalPath))-ine $full){Fail-M12 'OUTPUT'};return $i}finally{$s.Dispose()} }
function Open-M12ExecutableHandle([string]$Path){$full=[IO.Path]::GetFullPath($Path);Assert-M12TrustedTree $full;$s=[IO.FileStream]::new($full,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$i=[M12OutputFile]::Read($s);if($i.Links-ne 1-or[IO.Path]::GetFullPath((Normalize-M12NativePath $i.FinalPath))-ine$full){$s.Dispose();Fail-M12 'EXECUTABLE'};return [pscustomobject]@{Stream=$s;Identity=$i}}
function Write-M12Utf8Json([string] $Path,[object] $Value,[string] $ExpectedDirectory) { $full=[IO.Path]::GetFullPath($Path);if(Test-Path -LiteralPath $full){Fail-M12 'OUTPUT'};$b=[Text.UTF8Encoding]::new($false).GetBytes(($Value|ConvertTo-Json -Depth 32 -Compress)+"`n");if($b.Length -lt 1-or$b.Length -gt 32768-or @($b|Where-Object{$_-eq 13}).Count-ne 0-or @($b|Where-Object{$_-eq 10}).Count-ne 1){Fail-M12 'OUTPUT'};$s=[IO.FileStream]::new($full,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);$before=$null;try{$s.Write($b,0,$b.Length);$s.Flush($true);$before=[M12OutputFile]::Read($s);if($before.Links -ne 1-or [IO.Path]::GetFullPath((Normalize-M12NativePath $before.FinalPath))-ine $full){Fail-M12 'OUTPUT'}}finally{$s.Dispose()};$after=Assert-M12OutputFileIdentity $full $ExpectedDirectory;if($null-eq$before-or$after.Volume-ne$before.Volume-or$after.High-ne$before.High-or$after.Low-ne$before.Low-or$after.Links-ne 1){Fail-M12 'OUTPUT'};$name=[IO.Path]::GetFileName($full);if($script:M12OutputIdentities.ContainsKey($name)){Fail-M12 'OUTPUT'};$script:M12OutputIdentities[$name]=$after;$script:M12OutputHashes[$name]=Get-M12Sha256 $full;$script:M12OutputBytes[$name]=$b }
function Read-M12LockedBytes([string]$Path,[string]$ExpectedDirectory,[int]$MaximumBytes){$full=[IO.Path]::GetFullPath($Path);$directory=[IO.Path]::GetFullPath($ExpectedDirectory).TrimEnd('\\','/');if(-not$full.StartsWith($directory+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){Fail-M12 'OUTPUT'};Assert-M12TrustedTree $full;$s=[IO.FileStream]::new($full,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::None);try{$identity=[M12OutputFile]::Read($s);if($identity.Links-ne 1-or[IO.Path]::GetFullPath((Normalize-M12NativePath $identity.FinalPath))-ine$full-or$s.Length-lt 1-or$s.Length-gt$MaximumBytes){Fail-M12 'OUTPUT'};$bytes=[byte[]]::new([int]$s.Length);$offset=0;while($offset-lt$bytes.Length){$n=$s.Read($bytes,$offset,$bytes.Length-$offset);if($n-le 0){Fail-M12 'OUTPUT'};$offset+=$n};return [pscustomobject]@{Identity=$identity;Bytes=$bytes}}finally{$s.Dispose()}}
function Get-M12Sha256([string] $Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() }
function Read-M12ClosedJson([string] $Path,[string[]]$ExpectedNames=$null) { $info=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;$b=[IO.File]::ReadAllBytes($Path);if($info.PSIsContainer-or$info.Length-lt 1-or$info.Length-gt 32768-or$b.Length-ne$info.Length-or$b[-1]-ne 10-or @($b|Where-Object{$_-eq 13}).Count-ne 0-or @($b|Where-Object{$_-eq 10}).Count-ne 1-or($b.Length-ge 3-and$b[0]-eq 239-and$b[1]-eq 187-and$b[2]-eq 191)){Fail-M12 'OUTPUT'};$doc=$null;try{$doc=[Text.Json.JsonDocument]::Parse($b);if($doc.RootElement.ValueKind-ne [Text.Json.JsonValueKind]::Object){Fail-M12 'OUTPUT'};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($p in $doc.RootElement.EnumerateObject()){if(-not$seen.Add($p.Name)){Fail-M12 'OUTPUT'}};$value=[Text.UTF8Encoding]::new($false,$true).GetString($b)|ConvertFrom-Json -DateKind String -ErrorAction Stop}catch{Fail-M12 'OUTPUT'}finally{if($null-ne$doc){$doc.Dispose()}};if($null-ne$ExpectedNames-and(@($value.PSObject.Properties.Name)-join '|')-cne($ExpectedNames-join '|')){Fail-M12 'OUTPUT'};return $value }
function Read-M12ClosedJsonBytes([byte[]]$Bytes,[string[]]$ExpectedNames=$null){if($Bytes.Length-lt 1-or$Bytes.Length-gt 32768-or$Bytes[-1]-ne 10-or@($Bytes|Where-Object{$_-eq 13}).Count-ne 0-or@($Bytes|Where-Object{$_-eq 10}).Count-ne 1-or($Bytes.Length-ge 3-and$Bytes[0]-eq 239-and$Bytes[1]-eq 187-and$Bytes[2]-eq 191)){Fail-M12 'OUTPUT'};$doc=$null;try{$doc=[Text.Json.JsonDocument]::Parse($Bytes);if($doc.RootElement.ValueKind-ne [Text.Json.JsonValueKind]::Object){Fail-M12 'OUTPUT'};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($p in $doc.RootElement.EnumerateObject()){if(-not$seen.Add($p.Name)){Fail-M12 'OUTPUT'}};$value=[Text.UTF8Encoding]::new($false,$true).GetString($Bytes)|ConvertFrom-Json -DateKind String -ErrorAction Stop}catch{Fail-M12 'OUTPUT'}finally{if($null-ne$doc){$doc.Dispose()}};if($null-ne$ExpectedNames-and(@($value.PSObject.Properties.Name)-join '|')-cne($ExpectedNames-join '|')){Fail-M12 'OUTPUT'};return $value}
function Assert-M12JsonTypes([string]$Path,[hashtable]$ExpectedTypes){$doc=$null;try{$doc=[Text.Json.JsonDocument]::Parse([IO.File]::ReadAllBytes($Path));$k=@{string=[Text.Json.JsonValueKind]::String;number=[Text.Json.JsonValueKind]::Number;integer=[Text.Json.JsonValueKind]::Number};foreach($e in $ExpectedTypes.GetEnumerator()){$p=$doc.RootElement.GetProperty($e.Key);if($e.Value-eq'boolean'){if($p.ValueKind -notin @([Text.Json.JsonValueKind]::True,[Text.Json.JsonValueKind]::False)){Fail-M12 'OUTPUT'}}elseif($p.ValueKind-ne$k[$e.Value]){Fail-M12 'OUTPUT'};if($e.Value-eq'integer'){$n=0;if(-not$p.TryGetInt32([ref]$n)){Fail-M12 'OUTPUT'}}}}catch{Fail-M12 'OUTPUT'}finally{if($null-ne$doc){$doc.Dispose()}}}
function Assert-M12JsonTypesBytes([byte[]]$Bytes,[hashtable]$ExpectedTypes){$doc=$null;try{$doc=[Text.Json.JsonDocument]::Parse($Bytes);$k=@{string=[Text.Json.JsonValueKind]::String;number=[Text.Json.JsonValueKind]::Number;integer=[Text.Json.JsonValueKind]::Number};foreach($e in $ExpectedTypes.GetEnumerator()){$p=$doc.RootElement.GetProperty($e.Key);if($e.Value-eq'boolean'){if($p.ValueKind -notin @([Text.Json.JsonValueKind]::True,[Text.Json.JsonValueKind]::False)){Fail-M12 'OUTPUT'}}elseif($p.ValueKind-ne$k[$e.Value]){Fail-M12 'OUTPUT'};if($e.Value-eq'integer'){$n=0;if(-not$p.TryGetInt32([ref]$n)){Fail-M12 'OUTPUT'}}}}catch{Fail-M12 'OUTPUT'}finally{if($null-ne$doc){$doc.Dispose()}}}
function Assert-M12CollectorEvidence([object]$Result){$items=@($Result.collectorEvidence);if($items.Count-ne 14){Fail-M12 'TEST'};$seen=@{};$s=0;$p=0;$u=0;$ut=0;$uc=0;for($i=0;$i-lt$items.Count;$i++){$parts=[string]$items[$i]-split '\|',4;if($parts.Count-ne 4-or$parts[1]-cne$collectors[$i]-or$seen.ContainsKey($parts[1])){Fail-M12 'TEST'};$seen[$parts[1]]=$true;$expectedOrder=if($i-eq 13){15}else{$i+1};if($parts[0]-ne[string]$expectedOrder){Fail-M12 'TEST'};switch($parts[2]){'Succeeded'{if($parts[3]-cne'Completed'){Fail-M12 'TEST'};$s++}'Partial'{if($parts[3]-notin @('SourceRowLimit','ResponseByteLimit','BlockingGraphLimit','VisibilityIncomplete','OverlapDeduplicated')){Fail-M12 'TEST'};$p++}'Unsupported'{if($parts[3]-eq'TargetUnsupported'){$ut++}elseif($parts[3]-eq'CapabilityMissing'){$uc++}else{Fail-M12 'TEST'};$u++}default{Fail-M12 'TEST'}}};if($s-ne$result.succeededCount-or$p-ne$result.partialCount-or$u-ne$result.unsupportedCount-or$ut-ne$result.unsupportedTargetCount-or$uc-ne$result.unsupportedCapabilityCount){Fail-M12 'TEST'}}
function Read-M12RepoText([string] $Path,[int] $MaximumBytes=65536) { Assert-M12TrustedTree $Path; $i=Get-Item -LiteralPath $Path -Force -ErrorAction Stop; if($i.PSIsContainer -or $i.Length -lt 1 -or $i.Length -gt $MaximumBytes){Fail-M12 'COMMIT'}; try{return [Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($Path))}catch{Fail-M12 'COMMIT'} }
function Resolve-M12RepoPath([string] $Base,[string] $Relative) { if([string]::IsNullOrWhiteSpace($Relative)-or $Relative.Contains('..')-or $Relative.Contains([char]0)){Fail-M12 'COMMIT'}; $p=[IO.Path]::GetFullPath((Join-Path $Base $Relative));Assert-M12TrustedTree $p;return $p }
function Resolve-M12CanonicalRoot([string]$Requested,[string]$Authority) {
 if([string]::IsNullOrWhiteSpace($Requested)-or[string]::IsNullOrWhiteSpace($Authority)){Fail-M12 'ROOT'}
 try{$requestedFull=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $Requested -ErrorAction Stop).Path);$authorityFull=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $Authority -ErrorAction Stop).Path);Assert-M12TrustedTree $requestedFull;Assert-M12TrustedTree $authorityFull;if(-not[String]::Equals($requestedFull.TrimEnd('\','/'),$authorityFull.TrimEnd('\','/'),[StringComparison]::OrdinalIgnoreCase)){Fail-M12 'ROOT'};foreach($relative in @('tools/run-m12-reports-certification.ps1','tests/SqlObserver.IntegrationTests.PostgreSql/SqlObserver.IntegrationTests.PostgreSql.csproj','release/certification/m12-reports-contract.v1.json','release/certification/m12-reports-contract.v1.schema.json','release/certification/m12-reports-contract.v1.sha256')){$required=Resolve-M12RepoPath $requestedFull $relative;if(-not(Test-Path -LiteralPath $required -PathType Leaf)){Fail-M12 'ROOT'}};return$requestedFull}catch{Fail-M12 'ROOT'}
}
function Get-M12CurrentCommit([string] $Root) { $entry=Join-Path $Root '.git';Assert-M12TrustedTree $entry;$item=Get-Item -LiteralPath $entry -Force; $gd=if($item.PSIsContainer){[IO.Path]::GetFullPath($entry)}else{$t=(Read-M12RepoText $entry 4096).TrimEnd("`r","`n");if($t -notmatch '^gitdir: ([^\r\n]+)$'){Fail-M12 'COMMIT'};[IO.Path]::GetFullPath((Join-Path $Root $Matches[1]))};Assert-M12TrustedTree $gd;$common=$gd;$cd=Join-Path $gd 'commondir';if(Test-Path -LiteralPath $cd){$b=[IO.File]::ReadAllBytes($cd);if($b.Length -lt 2 -or $b.Length -gt 32){Fail-M12 'COMMIT'};$ct=[Text.UTF8Encoding]::new($false,$true).GetString($b);if($ct -cne "../..`n"){Fail-M12 'COMMIT'};$common=[IO.Path]::GetFullPath((Join-Path $gd '../..'));Assert-M12TrustedTree $common};$h=(Read-M12RepoText (Join-Path $gd 'HEAD') 4096).TrimEnd("`r","`n");if($h -match '^[0-9a-f]{40}$'){return $h};if($h -notmatch '^ref: (refs/[A-Za-z0-9._/-]+)$'){Fail-M12 'COMMIT'};$ref=$Matches[1];$rp=Resolve-M12RepoPath $common $ref;if(Test-Path -LiteralPath $rp){$s=(Read-M12RepoText $rp 4096).Trim();if($s -match '^[0-9a-f]{40}$'){return $s};Fail-M12 'COMMIT'};$p=Join-Path $common 'packed-refs';if(-not(Test-Path -LiteralPath $p)){Fail-M12 'COMMIT'};foreach($line in (Read-M12RepoText $p 1048576)-split "`n"){if($line.TrimEnd("`r") -match ('^([0-9a-f]{40}) '+[regex]::Escape($ref)+'$')){return $Matches[1]}};Fail-M12 'COMMIT' }
function Remove-M12SafeDescendants([string]$Path,[string]$Root){$full=[IO.Path]::GetFullPath($Path);$rootFull=[IO.Path]::GetFullPath($Root);if(-not$full.StartsWith($rootFull+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){Fail-M12 'PROCESS'};$item=Get-Item -LiteralPath $full -Force -ErrorAction Stop;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne 0){Fail-M12 'PROCESS'};if($item.PSIsContainer){foreach($child in @(Get-ChildItem -LiteralPath $full -Force -ErrorAction Stop)){Remove-M12SafeDescendants $child.FullName $rootFull};Remove-Item -LiteralPath $full -Force -ErrorAction Stop}else{Remove-Item -LiteralPath $full -Force -ErrorAction Stop};if(Test-Path -LiteralPath $full){Fail-M12 'PROCESS'}}
function Remove-M12SafeTree([string] $Path,[string] $AllowedParent) { if(-not(Test-Path -LiteralPath $Path -ErrorAction Stop)){return};$full=[IO.Path]::GetFullPath($Path);$parent=[IO.Path]::GetFullPath($AllowedParent).TrimEnd('\\','/');if(-not $full.StartsWith($parent+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){return};if([IO.Path]::GetFileName($full)-notmatch '^\.(pending|verify)-[0-9a-fA-F-]{36}$'){return};Assert-M12TrustedTree $full;foreach($i in @(Get-ChildItem -LiteralPath $full -Force -ErrorAction Stop)){Remove-M12SafeDescendants $i.FullName $full};Remove-Item -LiteralPath $full -Force -ErrorAction Stop;if(Test-Path -LiteralPath $full){Fail-M12 'PROCESS'} }
function Remove-M12RawTestDirectory([string] $Path) {
    if (-not (Test-Path -LiteralPath $Path -PathType Container)) { return }
    Assert-M12TrustedTree $Path
    foreach ($entry in @(Get-ChildItem -LiteralPath $Path -Force)) {
        if ($entry.PSIsContainer -or ($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { Fail-M12 'OUTPUT' }
        [void](Assert-M12OutputFileIdentity $entry.FullName $Path)
        Remove-Item -LiteralPath $entry.FullName -Force -ErrorAction Stop
    }
    Remove-Item -LiteralPath $Path -Force -ErrorAction Stop
}
function Remove-M12RawArtifactsDirectory([string]$Path,[string]$Build){if(-not(Test-Path -LiteralPath $Path)){return};$full=[IO.Path]::GetFullPath($Path);$parent=[IO.Path]::GetFullPath($Build).TrimEnd('\\','/');if(-not$full.StartsWith($parent+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)-or[IO.Path]::GetFileName($full)-cne'raw'){Fail-M12 'OUTPUT'};Assert-M12TrustedTree $full;foreach($entry in @(Get-ChildItem -LiteralPath $full -Force)){Remove-M12SafeDescendants $entry.FullName $full};Remove-Item -LiteralPath $full -Force -ErrorAction Stop;if(Test-Path -LiteralPath $full){Fail-M12 'OUTPUT'}}
function Assert-M12ReleaseHost([string] $SelectedProfile,[string] $Environment,[string[]] $AllowedEnvironments) { if(-not $IsWindows -or -not [Environment]::Is64BitOperatingSystem -or -not [Environment]::Is64BitProcess -or [Runtime.InteropServices.RuntimeInformation]::OSArchitecture -ne [Runtime.InteropServices.Architecture]::X64 -or [Runtime.InteropServices.RuntimeInformation]::ProcessArchitecture -ne [Runtime.InteropServices.Architecture]::X64 -or $SelectedProfile -cne 'Release'){Fail-M12 'HOST'};if([Environment]::GetEnvironmentVariable('SQLOBSERVER_VALIDATION_PROFILE') -cne 'Release'){Fail-M12 'HOST'};if($Environment -cnotin $AllowedEnvironments){Fail-M12 'HOST'};try{$os=Get-CimInstance Win32_OperatingSystem -ErrorAction Stop;$expected=if($Environment -ceq 'release-windows-server-2022'){'Microsoft Windows Server 2022'}else{'Microsoft Windows Server 2025'};if($os.ProductType -notin @(2,3)-or -not ([string]$os.Caption).StartsWith($expected,[StringComparison]::Ordinal)){Fail-M12 'HOST'}}catch{Fail-M12 'HOST'} }

function Assert-M12ObservedPidsExited([Collections.Generic.HashSet[int]]$ProcessIds){if(-not$IsWindows){return};foreach($id in $ProcessIds){$remaining=@(Get-CimInstance Win32_Process -Filter "ProcessId=$id" -ErrorAction Stop);if($remaining.Count-ne 0){Fail-M12 'PROCESS'}}}
function Assert-M12NoDescendants([int[]]$ProcessIds){if(-not$IsWindows){return};$roots=[Collections.Generic.HashSet[int]]::new();foreach($id in $ProcessIds){[void]$roots.Add($id)};$discoveredPids=[Collections.Generic.HashSet[int]]::new();$stableEmptySweeps=0;while($stableEmptySweeps-lt 3){try{$snapshot=@(Get-CimInstance Win32_Process -ErrorAction Stop);if($snapshot.Count-gt 4096){Fail-M12 'PROCESS'};$children=@{};foreach($proc in $snapshot){$parent=[int]$proc.ParentProcessId;if(-not$children.ContainsKey($parent)){$children[$parent]=[Collections.Generic.List[int]]::new()};$children[$parent].Add([int]$proc.ProcessId)};$queue=[Collections.Generic.Queue[int]]::new();foreach($root in $roots){$queue.Enqueue($root)};$seen=[Collections.Generic.HashSet[int]]::new();$descendantsThisSweep=0;while($queue.Count-gt 0){$current=$queue.Dequeue();if(-not$seen.Add($current)){continue};if($children.ContainsKey($current)){foreach($child in $children[$current]){if($roots.Contains($child)){continue};$descendantsThisSweep++;if($descendantsThisSweep-gt 256){Fail-M12 'PROCESS'};[void]$discoveredPids.Add($child);$queue.Enqueue($child)}}};$allIds=[Collections.Generic.List[int]]::new();foreach($id in $roots){$allIds.Add($id)};foreach($id in $discoveredPids){$allIds.Add($id)};foreach($id in $allIds){if(@($snapshot|Where-Object{[int]$_.ProcessId-eq$id}).Count-ne 0){Fail-M12 'PROCESS'}};if($descendantsThisSweep-ne 0){Fail-M12 'PROCESS'};$stableEmptySweeps++}catch{if($_.Exception.Message -like 'M12-REPORTS-*'){throw};Fail-M12 'PROCESS'};if($stableEmptySweeps-lt 3){[Threading.Thread]::Sleep(50)}}}
function Invoke-M12BoundedProcess([string]$Exe,[string[]]$Arguments,[string]$WorkingDirectory,[object]$Job){$p=$Job.ManagedProcess;$observedPids=[Collections.Generic.HashSet[int]]::new();[void]$observedPids.Add($p.Id);$o=[IO.MemoryStream]::new();$e=[IO.MemoryStream]::new();$ob=[byte[]]::new(4096);$eb=[byte[]]::new(4096);$ot=$Job.StandardOutput.ReadAsync($ob,0,$ob.Length);$et=$Job.StandardError.ReadAsync($eb,0,$eb.Length);$deadline=[Environment]::TickCount64+$MaximumMilliseconds;$od=$false;$ed=$false;$large=$false;$timeout=$false;try{while(-not($od-and$ed-and$p.HasExited)){foreach($pid in @($Job.ProcessIds)){[void]$observedPids.Add($pid)};[Threading.Tasks.Task]::Delay(25).GetAwaiter().GetResult();if(-not$od-and$ot.IsCompleted){$n=$ot.GetAwaiter().GetResult();if($n-eq 0){$od=$true}elseif($o.Length+$n-gt$MaximumOutput){$large=$true}else{$o.Write($ob,0,$n);$ot=$Job.StandardOutput.ReadAsync($ob,0,$ob.Length)}};if(-not$ed-and$et.IsCompleted){$n=$et.GetAwaiter().GetResult();if($n-eq 0){$ed=$true}elseif($e.Length+$n-gt$MaximumError){$large=$true}else{$e.Write($eb,0,$n);$et=$Job.StandardError.ReadAsync($eb,0,$eb.Length)}};if($large-or[Environment]::TickCount64-ge$deadline){$timeout=-not$large;$Job.Terminate();break}};foreach($pid in @($Job.ProcessIds)){[void]$observedPids.Add($pid)};$exitCode=if($timeout-or$large){-1}else{$Job.ExitCode};if($Job.ActiveProcesses-gt 0){$Job.Terminate()};if(-not$Job.WaitForZero(2000)-or$Job.ActiveProcesses-ne 0){Fail-M12 'PROCESS'};Assert-M12ObservedPidsExited $observedPids;Assert-M12NoDescendants @($observedPids);return [pscustomobject]@{ExitCode=$exitCode;Output=[Text.Encoding]::UTF8.GetString($o.ToArray());Error=[Text.Encoding]::UTF8.GetString($e.ToArray());TooLarge=$large;TimedOut=$timeout}}finally{$cleanupFailures=[Collections.Generic.List[Exception]]::new();try{$o.Dispose()}catch{$cleanupFailures.Add($_.Exception)};try{$e.Dispose()}catch{$cleanupFailures.Add($_.Exception)};if($cleanupFailures.Count-ne 0){throw [AggregateException]::new($cleanupFailures)}}}

function Assert-ReportsConnection([string]$Value,[string]$Root){
    if([string]::IsNullOrWhiteSpace($Value)-or$Value.Length-gt 4096){Fail-M12 'INPUT'}
    $parts=[ordered]@{}
    foreach($segment in [regex]::Split($Value,';')){
        $text=$segment.Trim();if($text.Length-eq 0){Fail-M12 'INPUT'}
        $equals=$text.IndexOf('=');if($equals-lt 1){Fail-M12 'INPUT'}
        $key=$text.Substring(0,$equals).Trim().ToLowerInvariant();$val=$text.Substring($equals+1).Trim()
        if($key.Length-eq 0-or$parts.Contains($key)-or$val.Length-eq 0){Fail-M12 'INPUT'}
        if(($val.StartsWith('"')-or$val.StartsWith("'")) -and (($val.Length-lt 2)-or$val[$val.Length-1]-ne$val[0])){Fail-M12 'INPUT'}
        if($val.Length-ge 2 -and (($val[0]-eq '"'-and$val[$val.Length-1]-eq '"')-or($val[0]-eq "'"-and$val[$val.Length-1]-eq "'"))){$val=$val.Substring(1,$val.Length-2)}
        if($val.Contains('"')-or$val.Contains("'")){Fail-M12 'INPUT'}
        $parts[$key]=$val
    }
    $allowed=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase);foreach($key in @('host','server','data source','database','initial catalog','ssl mode','port')){[void]$allowed.Add($key)}
    foreach($key in $parts.Keys){if(-not$allowed.Contains($key)){Fail-M12 'INPUT'}}
    $hostKeys=@('host','server','data source');$databaseKeys=@('database','initial catalog')
    $hostMatches=@($hostKeys|Where-Object{$parts.Contains($_)});$databaseMatches=@($databaseKeys|Where-Object{$parts.Contains($_)})
    if($hostMatches.Count-ne 1-or$databaseMatches.Count-ne 1-or-not$parts.Contains('ssl mode')){Fail-M12 'INPUT'}
    if($parts['ssl mode'] -cne 'VerifyFull'){Fail-M12 'INPUT'}
    if([string]::IsNullOrWhiteSpace($parts[$databaseMatches[0]])){Fail-M12 'INPUT'}
    if($parts.Contains('port')){$port=0;if(-not[int]::TryParse($parts['port'],[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$port)-or$port-lt 1-or$port-gt 65535){Fail-M12 'INPUT'}}
    $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
    $hosts=[regex]::Split([string]$parts[$hostMatches[0]],',');if($hosts.Count-lt 2){Fail-M12 'INPUT'}
    foreach($rawHost in $hosts){$hostName=$rawHost.Trim();if([string]::IsNullOrWhiteSpace($hostName)){Fail-M12 'INPUT'};$address=[Net.IPAddress]::None;$ipText=$hostName.TrimStart('[').TrimEnd(']');if([Net.IPAddress]::TryParse($ipText,[ref]$address)-and[Net.IPAddress]::IsLoopback($address)){Fail-M12 'INPUT'};if(-not$seen.Add($hostName)-or$hostName-match'(?i)^(\.|localhost|local|127(?:\.\d{1,3}){3}|0\.0\.0\.0|::1|\[::1\]|desktop|workstation|(?:tcp:)?(local|localhost))$'-or$hostName-match'(?i)(desktop|workstation|localhost|loopback)'){Fail-M12 'INPUT'}}
}
function Assert-M12ClosedSchema([object]$Node){if($null-eq$Node){return};if($Node.PSObject.Properties.Name-contains'additionalProperties'-and$Node.additionalProperties-ne$false){Fail-M12 'CONTRACT'};foreach($p in $Node.PSObject.Properties){if($p.Name-eq'properties'){foreach($child in $p.Value.PSObject.Properties){Assert-M12ClosedSchema $child.Value}}elseif($p.Name-eq'prefixItems'){foreach($child in @($p.Value)){Assert-M12ClosedSchema $child}}elseif($p.Name-eq'items' -and $p.Value -isnot [bool]){Assert-M12ClosedSchema $p.Value}}}
function Assert-M12ContractValues([object]$c,[object]$s,[string]$Root){$names=@($c.PSObject.Properties.Name);$expected=@('$schema','schemaVersion','contractId','producerId','definitionVersion','reportKinds','sections','formats','bounds','encoding','caseMappings','assetPins');if(($names-join'|')-cne($expected-join'|')-or$c.'$schema'-cne'm12-reports-contract.v1.schema.json'-or$c.schemaVersion-ne 1-or$c.contractId-cne'm12-reports-exports'-or$c.producerId-cne$ProducerId-or$c.definitionVersion-ne 1){Fail-M12 'CONTRACT'};if((@($c.reportKinds)-join'|')-cne'instance-health|performance-window|incident-evidence|capacity-readiness'-or(@($c.sections)-join'|')-cne'health|performance|incidents|capacity'){Fail-M12 'CONTRACT'};if($c.formats.html-cne'inert-printable'-or$c.formats.csv-cne'utf-8-per-section'){Fail-M12 'CONTRACT'};$bounds=@{requestBytes=65536;pageRows=200;htmlRows=2000;materializationRows=10000;responseBytes=1048576;materializationBytes=8388608;detailedWindowDays=7;trendWindowDays=31;repositoryTimeoutSeconds=5;totalTimeoutSeconds=15;actorConcurrency=2;globalConcurrency=16;retentionHours=24};foreach($p in $bounds.Keys){if($c.bounds.$p-ne$bounds[$p]){Fail-M12 'CONTRACT'}};if($c.encoding.html-cne'html-encode-text-and-attributes'-or$c.encoding.csv-cne'rfc4180'-or$c.encoding.formulaNeutralization-ne$true-or(@($c.encoding.formulaSentinels)-join'|')-cne'=|+|-|@'-or$c.encoding.controlCharacterNormalization-ne$true-or$c.encoding.utf8Bom-ne$false){Fail-M12 'CONTRACT'};$map=@($c.caseMappings);if($map.Count-ne 3){Fail-M12 'CONTRACT'};foreach($id in $CaseMap.Keys){$entry=$map|Where-Object { $_.caseId -ceq $id };$expectedFacts=@($CaseMap[$id].Facts.Keys);if($null-eq$entry-or$entry.Count-ne 1-or$entry.testName-cne$CaseMap[$id].Test-or(@($entry.facts.PSObject.Properties.Name)-join'|')-cne($expectedFacts-join'|')){Fail-M12 'CONTRACT'};foreach($fact in $expectedFacts){if($entry.facts.$fact-ne$CaseMap[$id].Facts[$fact]){Fail-M12 'CONTRACT'}}};if((@($c.assetPins.PSObject.Properties.Name)-join'|')-cne(@($ApprovedAssetPins.Keys)-join'|')){Fail-M12 'CONTRACT'};foreach($a in $ApprovedAssetPins.Keys){if((Get-M12Sha256(Join-Path $Root $a))-cne$ApprovedAssetPins[$a]-or[string]$c.assetPins.$a-cne$ApprovedAssetPins[$a]){Fail-M12 'CONTRACT'}};$matrixPath=Join-Path $Root 'release/certification/m12-certification-matrix.v1.json';if((Get-M12Sha256 $matrixPath)-cne'8b87625c2a56ea07b1dfe826201557e54891341803a75f2a77d2296509f07aac'){Fail-M12 'CONTRACT'};$matrix=Get-Content -LiteralPath $matrixPath -Raw|ConvertFrom-Json;$lane=@($matrix.lanes|Where-Object { $_.laneId -ceq 'reports' });if($lane.Count-ne 1-or$lane[0].producerId-cne$ProducerId-or$lane[0].implementationStatus-cne'pending'){Fail-M12 'CONTRACT'};$matrixCases=@($lane[0].cases);if($matrixCases.Count-ne 3){Fail-M12 'CONTRACT'};foreach($id in $CaseMap.Keys){$mc=@($matrixCases|Where-Object { $_.caseId -ceq $id });if($mc.Count-ne 1-or$mc[0].producerId-cne$ProducerId-or$mc[0].implementationStatus-cne'pending'-or(@($mc[0].environment.identities)-join'|')-cne'release-windows-server-2022|release-windows-server-2025'-or(@($mc[0].artifactKinds)-join'|')-cne$ArtifactKind){Fail-M12 'CONTRACT'}};Assert-M12ClosedSchema $s}
function Assert-ReportsContract([string]$Root){$cp=Join-Path $Root 'release/certification/m12-reports-contract.v1.json';$sp=Join-Path $Root 'release/certification/m12-reports-contract.v1.schema.json';$pp=Join-Path $Root 'release/certification/m12-reports-contract.v1.sha256';if((Get-M12Sha256 $cp)-cne$ApprovedContractSha256-or(Get-M12Sha256 $sp)-cne$ApprovedContractSchemaSha256){Fail-M12 'CONTRACT'};$pin=[Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes($pp));if($pin-ne($ApprovedContractSha256+'  m12-reports-contract.v1.json'+[char]10+$ApprovedContractSchemaSha256+'  m12-reports-contract.v1.schema.json'+[char]10)){Fail-M12 'CONTRACT'};$c=Get-Content -LiteralPath $cp -Raw|ConvertFrom-Json;$s=Get-Content -LiteralPath $sp -Raw|ConvertFrom-Json;if($s.additionalProperties-ne$false-or$c.'$schema'-cne'm12-reports-contract.v1.schema.json'-or$c.producerId-cne$ProducerId){Fail-M12 'CONTRACT'};Assert-M12ContractValues $c $s $Root;return $c}
function Assert-M12FactShape([object]$Facts,[string[]]$Names,[string[]]$Types){if($null-eq$Facts-or$Names.Count-ne$Types.Count-or(@($Facts.PSObject.Properties.Name)-join'|')-cne($Names-join'|')){Fail-M12 'TEST'};for($i=0;$i-lt$Names.Count;$i++){$p=$Facts.PSObject.Properties[$Names[$i]];if($null-eq$p){Fail-M12 'TEST'};$value=$p.Value;switch($Types[$i]){'bool'{if($value-isnot[bool]){Fail-M12 'TEST'}}'int'{if($value-isnot[int]-and$value-isnot[long]-and$value-isnot[uint64]){Fail-M12 'TEST'};if([long]$value-lt 0){Fail-M12 'TEST'}}'string'{if($value-isnot[string]){Fail-M12 'TEST'}}'array'{if($value-isnot[Collections.IEnumerable]-or$value-is[string]){Fail-M12 'TEST'}}'null'{if($null-ne$value){Fail-M12 'TEST'}}}}
}
function Read-M12ReportsTrx([string]$Path,[string]$ExpectedTestName){$locked=Read-M12LockedBytes $Path (Split-Path $Path -Parent) 16777216;$text=[Text.UTF8Encoding]::new($false,$true).GetString($locked.Bytes);if($text-match'(?is)<!DOCTYPE'){Fail-M12 'TEST'};$xml=[Xml.XmlDocument]::new();$xml.XmlResolver=$null;$stream=[IO.MemoryStream]::new($locked.Bytes);try{$xml.Load($stream)}catch{Fail-M12 'TEST'}finally{$stream.Dispose()};if($null-ne$xml.DocumentType){Fail-M12 'TEST'};$roots=@($xml.SelectNodes('/*'));if($roots.Count-ne 1-or$roots[0].LocalName-cne'TestRun'){Fail-M12 'TEST'};$results=@($xml.SelectNodes('//*[local-name()="UnitTestResult"]'));$units=@($xml.SelectNodes('//*[local-name()="UnitTest"]'));$summaries=@($xml.SelectNodes('//*[local-name()="ResultSummary"]'));if($results.Count-ne 1-or$units.Count-ne 1-or$summaries.Count-ne 1){Fail-M12 'TEST'};$result=$results[0];$unit=$units[0];if($result.ParentNode.LocalName-cne'Results'-or$unit.ParentNode.LocalName-cne'TestDefinitions'-or$summaries[0].ParentNode.LocalName-cne'TestRun'-or[string]$summaries[0].outcome-cne'Completed'-or[string]$result.testName-cne$ExpectedTestName-or[string]$unit.name-cne$ExpectedTestName-or[string]$result.testId-cne[string]$unit.id-or[string]$result.outcome-cne'Passed'){Fail-M12 'TEST'};$counterNodes=@($summaries[0].ChildNodes|Where-Object LocalName -ceq'Counters');if($counterNodes.Count-ne 1){Fail-M12 'TEST'};$counter=$counterNodes[0];$expectedCounters=[ordered]@{total=1;executed=1;passed=1;failed=0;error=0;timeout=0;aborted=0;inconclusive=0;notExecuted=0;warning=0};foreach($name in $expectedCounters.Keys){$attr=$counter.Attributes[$name];$number=0;if($null-eq$attr-or-not[int]::TryParse($attr.Value,[Globalization.NumberStyles]::Integer,[Globalization.CultureInfo]::InvariantCulture,[ref]$number)-or$number-ne$expectedCounters[$name]){Fail-M12 'TEST'}};return [pscustomobject]@{TestCount=$results.Count;Bytes=$locked.Bytes;Identity=$locked.Identity}}
function Assert-LiveReportsResult([object]$v,[object]$case,[int]$ExpectedTestCount){if((@($v.PSObject.Properties.Name)-join'|')-cne'schemaVersion|caseId|status|testName|testCount|facts'){Fail-M12 'TEST'};if($v.schemaVersion-ne 1-or$v.caseId-cne$CaseId-or$v.status-cne'passed'-or$v.testName-cne$case.Test-or$v.testCount-ne$ExpectedTestCount){Fail-M12 'TEST'};if($case.ReportKind-eq'report'){$names=@('reports','exports','reportKind','snapshotScoped','audited','idempotentReplay','targetIsolation','roles','testCount','observedPostgreSqlVersion');$types=@('bool','bool','string','bool','bool','bool','bool','bool','int','int')}elseif($case.ReportKind-eq'export'){$names=@('reports','exports','reportKind','inertHtml','rfc4180','formulaNeutralization','formulaSentinels','testCount','observedPostgreSqlVersion');$types=@('bool','bool','string','bool','bool','bool','int','int','int')}else{$names=@('reports','exports','reportKind','definitions','sections','page200','html2000','export10000','responseBytes','materializationBytes','observedPostgreSqlVersion');$types=@('bool','bool','null','int','array','bool','bool','bool','int','int','int')};Assert-M12FactShape $v.facts $names $types;if($v.facts.reports-ne$case.Reports-or$v.facts.exports-ne$case.Exports-or$case.ReportKind-ne$v.facts.reportKind-or$v.facts.testCount-ne 1-or$v.facts.observedPostgreSqlVersion-lt 1-or$v.facts.observedPostgreSqlVersion-gt 99){Fail-M12 'TEST'};if($case.Reports-and$case.Exports-and($v.facts.definitions-ne 4-or(@($v.facts.sections)-join'|')-cne'health|performance|incidents|capacity'-or-not$v.facts.page200-or-not$v.facts.html2000-or-not$v.facts.export10000-or$v.facts.responseBytes-ne1048576-or$v.facts.materializationBytes-ne8388608)){Fail-M12 'TEST'};if($case.ReportKind-eq'report' -and(-not$v.facts.snapshotScoped-or-not$v.facts.audited-or-not$v.facts.idempotentReplay-or-not$v.facts.targetIsolation-or-not$v.facts.roles)){Fail-M12 'TEST'};if($case.ReportKind-eq'export' -and(-not$v.facts.inertHtml-or-not$v.facts.r