    $fullTestName="SqlObserver.IntegrationTests.PostgreSql.M12ReportsCertificationTests.$TestName";$args=@('test',$project,'--configuration','Release','--no-restore','/t:Rebuild','--output',$rawArtifacts,'--filter',"FullyQualifiedName=$fullTestName",'--logger',"trx;LogFileName=$TrxPath")
