    try{$executableHandle=Open-M12ExecutableHandle $dotnet;[Environment]::SetEnvironmentVariable('SQLOBSERVER_RELEASE_REPORTS_CASE',$CaseId);[Environment]::SetEnvironmentVariable('SQLOBSERVER_RELEASE_REPORTS_RESULT_PATH',(Join-Path $trxDirectory 'live-result.json'));$native=[M12SuspendedProcess]::Start($dotnet,[string[]]$args,$Root);$run=Invoke-M12BoundedProcess $dotnet $args $Root $native;if($run.TimedOut){Fail-M12 'TIMEOUT'};if($run.TooLarge-or$run.ExitCode-ne 0){Fail-M12 'TEST'};$resultPath=[Environment]::GetEnvironmentVariable('SQLOBSERVER_RELEASE_REPORTS_RESULT_PATH');if(-not(Test-Path -LiteralPath $resultPath -PathType Leaf)){Fail-M12 'TEST'};$locked=Read-M12LockedBytes $resultPath $trxDirectory 32768;$result=Read-M12ClosedJsonBytes $locked.Bytes @('schemaVersion','caseId','status','testName','testCount','facts');Assert-M12JsonTypesBytes $locked.Bytes @{schemaVersion='integer';caseId='string';status='string';testName='string';testCount='integer'};if($null-eq$result.facts){Fail-M12 'TEST'};$trxResult=Read-M12ReportsTrx $TrxPath $fullTestName;if($result.testCount-ne$trxResult.TestCount-or$trxResult.TestCount-ne 1){Fail-M12 'TEST'};return[pscustomobject]@{TestCount=$trxResult.TestCount;Result=$result;Trx=$trxResult}}
    finally{try{if($null-eq$native){$cleanupFailure=$true}else{if($native.ActiveProcesses-gt 0){$native.Terminate()};if(-not$native.WaitForZero(2000)-or$native.ActiveProcesses-ne 0){$cleanupFailure=$true}}}catch{$cleanupFailure=$true};try{if($null-ne$native){$native.Dispose()}}catch{$cleanupFailure=$true};try{[Environment]::SetEnvironmentVariable('SQLOBSERVER_RELEASE_REPORTS_CASE',$previousCase);[Environment]::SetEnvironmentVariable('SQLOBSERVER_RELEASE_REPORTS_RESULT_PATH',$previousResult)}catch{$cleanupFailure=$true};if($null-ne$executableHandle){$executableHandle.Stream.Dispose()};if($cleanupFailure){Fail-M12 'PROCESS'}}
}
